# Randomized parameter generator with internal DP to ensure nontrivial instances
from fractions import Fraction
from functools import lru_cache

def compute_prob(n, m, t):
    # DP over symmetric occupancy states: c completed types, and f_j for j=1..m-1
    @lru_cache(maxsize=None)
    def P(c, f_tuple):
        f = list(f_tuple)  # f[0] = count with 1 in hand, ..., f[m-2] = count with m-1 in hand
        # Premature stop if singletons reach threshold
        if f[0] >= t:
            return Fraction(0, 1)
        incomplete = n - c
        fsum = sum(f)
        f0 = incomplete - fsum  # types with 0 in hand and m remaining
        # Total remaining tiles
        T = f0 * m
        for j in range(m - 1):
            T += (m - (j + 1)) * f[j]
        if T == 0:
            # Bag exhausted successfully without triggering stop
            return Fraction(1, 1)
        res = Fraction(0, 1)
        # Transition j=0: draw new type
        if f0 > 0:
            f_next = f[:]
            f_next[0] += 1
            res += Fraction(f0 * m, T) * P(c, tuple(f_next))
        # Transitions j=1..m-2: advance partial sets
        for j in range(1, m - 1):
            fj = f[j - 1]
            rem = m - j
            if fj > 0:
                f_next = f[:]
                f_next[j - 1] -= 1
                f_next[j] += 1
                res += Fraction(fj * rem, T) * P(c, tuple(f_next))
        # Transition j=m-1: complete set and remove it
        fm1 = f[m - 2] if m >= 2 else 0
        if fm1 > 0:
            f_next = f[:]
            f_next[m - 2] -= 1
            res += Fraction(fm1 * 1, T) * P(c + 1, tuple(f_next))
        return res
    f_init = tuple(0 for _ in range(m - 1))
    return P(0, f_init)

# Try multiple times to get nontrivial parameters
for _ in range(200):
    m = 3 if rng.random() < 0.65 else 4
    if m == 3:
        n = rng.randint(6, 9)
        t = rng.randint(3, min(n - 1, 5))
    else:
        n = rng.randint(5, 6)
        t = rng.randint(3, min(n - 1, 4))
    prob = compute_prob(n, m, t)
    if prob > 0 and prob < 1:
        return {
            'n_types': n,
            'multiplicity': m,
            'threshold': t
        }
# Fallback deterministic instance known to be nontrivial in practice
n, m, t = 6, 3, 3
# Verify fallback
prob = compute_prob(n, m, t)
if prob <= 0 or prob >= 1:
    # If something degenerate occurs, perturb slightly
    n, m, t = 7, 3, 3
return {
    'n_types': n,
    'multiplicity': m,
    'threshold': t
}

